@sig trait ExecutionOutcomeAcquisition_Api {
  def id: Art.BridgeId
  def execution_outcome_Id : Art.PortId
  def outcome_boundary_facts_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var outcome_boundary_facts: Factory_Dispatch_Coordinator.OutcomeBoundaryFacts = $

  def put_outcome_boundary_facts(value : Factory_Dispatch_Coordinator.OutcomeBoundaryFacts) : Unit = {
    Contract(
      Modifies(outcome_boundary_facts),
      Ensures(
        outcome_boundary_facts == value
      )
    )
    Spec {
      outcome_boundary_facts = value
    }

    Art.putValue(outcome_boundary_facts_Id, Factory_Dispatch_Coordinator.OutcomeBoundaryFacts_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class ExecutionOutcomeAcquisition_Initialization_Api (
  val id: Art.BridgeId,
  val execution_outcome_Id : Art.PortId,
  val outcome_boundary_facts_Id : Art.PortId) extends ExecutionOutcomeAcquisition_Api

@datatype class ExecutionOutcomeAcquisition_Operational_Api (
  val id: Art.BridgeId,
  val execution_outcome_Id : Art.PortId,
  val outcome_boundary_facts_Id : Art.PortId) extends ExecutionOutcomeAcquisition_Api {

  // Logika spec var representing port state for incoming data port
  @spec var execution_outcome: Factory_Dispatch_Coordinator.ExecutionOutcome.Type = $

  def get_execution_outcome() : Option[Factory_Dispatch_Coordinator.ExecutionOutcome.Type] = {
    Contract(
      Ensures(
        Res == Some(execution_outcome)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.ExecutionOutcome.Type] = Art.getValue(execution_outcome_Id) match {
      case Some(Factory_Dispatch_Coordinator.ExecutionOutcome_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port execution_outcome.  Expecting 'Factory_Dispatch_Coordinator.ExecutionOutcome_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.ExecutionOutcome.Type]()
      case _ => None[Factory_Dispatch_Coordinator.ExecutionOutcome.Type]()
    }
    return value
  }
}
